from parser import (
    Program, VarDecl, Assignment, TypeCastAssignment, TypeOnlyAssignment,
    Gimmeh, Print, IfStmt, Loop, SwitchCase, ImplicitIT,
    Expression, Literal, VarRef,
    FunctionDef, FunctionCall, ReturnStmt, BreakStmt
)
# These are the node types generated by the parser.
# They represent the structure of the LOLCODE program (the Abstract Syntax Tree or AST).

import sys

class LOLRuntimeError(Exception):
    """
    Custom exception class for errors encountered during program execution (runtime).
    This helps distinguish interpreter errors from standard Python exceptions.
    """
    pass


# === || Environment || ===
class Environment:
    """
    Manages the scope/context for variables. It supports nested scopes (like function calls).
    This implements the **Lexical Scoping** rule.
    """
    def __init__(self, parent=None):
        # Dictionary to hold variables in the current scope.
        # Format: {variable_name: {"type": "...", "value": ...}}
        self.vars = {}
        # Reference to the outer/enclosing scope (used for nested function/block access).
        self.parent = parent

    def define(self, name, value):
        """
        Declares a new variable in the *current* scope.
        Used for initial declarations (e.g., I HAS A X).
        """
        self.vars[name] = value

    def set(self, name, value):
        """
        Assigns a new value to an *existing* variable.
        It searches up the scope chain (parent environments) to find where the variable was defined.
        Used for assignments (e.g., X R 10).
        """
        env = self.lookup_env(name)
        if env is None:
            # Variable must exist to be set.
            raise LOLRuntimeError(f"Variable '{name}' not declared.")
        env.vars[name] = value

    def get(self, name):
        """
        Retrieves the value of a variable, searching up the scope chain.
        """
        env = self.lookup_env(name)
        if env is None:
            # Variable must exist to be retrieved.
            raise LOLRuntimeError(f"Variable '{name}' not declared.")
        return env.vars[name]

    def lookup_env(self, name):
        """
        **Scope Resolution:** Searches for the environment object that contains the variable 'name'.
        It starts at the current environment and recursively checks the 'parent' until the global scope is reached.
        """
        env = self
        while env:
            if name in env.vars:
                return env
            env = env.parent # Move to the parent scope
        return None # Variable not found in any scope


